export const webApiDocOverrides: ApiOverrides = Object.fromEntries(
  [...new Set([...Object.keys(webApiOperationDescriptions), ...Object.keys(explicitWebApiDocOverrides)])]
    .map((key) => [
      key,
      {
        ...(webApiOperationDescriptions[key] === undefined ? {} : { description: webApiOperationDescriptions[key] }),
        ...(explicitWebApiDocOverrides[key] ?? {}),
      },
    ]),
);
